import SwiftUI

/// Figma icons (IconPark Outline 24px, 2px round strokes; plus the Word/Excel/PDF file-type marks).
/// The cases are generated by Tools/import_icons.py; this file only renders them.
extension DSIcon {
    /// Brand and file-type marks keep their own colours; everything else tints with `foregroundColor`.
    var keepsOriginalColors: Bool {
        switch self {
        case .brandMicrosoftWord, .brandMicrosoftExcel, .fileTypePdf: true
        default: false
        }
    }

    func image(size: CGFloat = 16) -> some View {
        Image("Icons/\(rawValue)")
            .renderingMode(keepsOriginalColors ? .original : .template)
            .resizable()
            .interpolation(.high)
            .frame(width: size, height: size)
    }
}
